+/**
+ * Regex patterns for detecting prompt injection attempts.
+ * These patterns contain injection-like strings by necessity.
+ */
+export const INJECTION_PATTERNS: Array<{ name: string; pattern: RegExp }> = [
+  { name: 'instruction-override', pattern: /ignore\s+(all\s+)?previous\s+instructions/i },
+  { name: 'role-hijack', pattern: /you\s+are\s+now\s+/i },
+  { name: 'context-reset', pattern: /forget\s+(everything|all)\s+(above|before)/i },
+  { name: 'system-escape', pattern: /<\/system>/i },
+  { name: 'new-instructions', pattern: /new\s+(system\s+)?instructions?:/i },
+  { name: 'developer-mode', pattern: /developer\s+mode\s+(enabled|activated)/i },
+  { name: 'disregard', pattern: /disregard\s+(all\s+)?(previous|prior|above)/i },
+];
+
+export function detectInjection(input: string): string | null {
+  for (const { name, pattern } of INJECTION_PATTERNS) {
+    if (pattern.test(input)) {
+      return name;
+    }
+  }
+  return null;
+}
